// Almacenamiento local para permitir gestión dinámica desde el panel admin y tienda pública
const StorageService = {
  getProducts: function() {
    const versionKey = 'wes_products_v7_catalog';
    const saved = localStorage.getItem(versionKey);
    if (!saved) {
      localStorage.setItem(versionKey, JSON.stringify(INITIAL_PRODUCTS));
      localStorage.setItem('wes_custom_products', JSON.stringify(INITIAL_PRODUCTS));
      return INITIAL_PRODUCTS;
    }
    try {
      const parsed = JSON.parse(saved);
      if (!Array.isArray(parsed) || parsed.length === 0 || !parsed[0].name) {
        localStorage.setItem(versionKey, JSON.stringify(INITIAL_PRODUCTS));
        localStorage.setItem('wes_custom_products', JSON.stringify(INITIAL_PRODUCTS));
        return INITIAL_PRODUCTS;
      }
      return parsed;
    } catch (e) {
      return INITIAL_PRODUCTS;
    }
  },

  saveProducts: function(products) {
    localStorage.setItem('wes_products_v7_catalog', JSON.stringify(products));
    localStorage.setItem('wes_custom_products', JSON.stringify(products));
    if (typeof window !== 'undefined' && window.WES_CATALOG_STATE) {
      window.WES_CATALOG_STATE.products = products;
    }
  },

  getQuotes: function() {
    const saved = localStorage.getItem('wes_quotes');
    if (!saved) {
      return [];
    }
    try { return JSON.parse(saved); } catch (e) { return []; }
  },

  saveQuotes: function(quotes) {
    localStorage.setItem('wes_quotes', JSON.stringify(quotes));
  },

  getSupportTickets: function() {
    const saved = localStorage.getItem('wes_support_tickets');
    if (!saved) { return []; }
    try { return JSON.parse(saved); } catch (e) { return []; }
  },

  saveSupportTickets: function(tickets) {
    localStorage.setItem('wes_support_tickets', JSON.stringify(tickets));
  },

  getCompanySettings: function() {
    const saved = localStorage.getItem('wes_company_settings');
    const defaults = {
      phone: '(849) 207-5474',
      whatsapp: '18492075474',
      whatsappDisplay: '(849) 207-5474',
      emailGeneral: 'wes.inform@gmail.com',
      emailSupport: 'wes.inform@gmail.com',
      address: 'Autopista Ramón Cáceres, Plaza Megatone, Moca, Rep. Dom.',
      scheduleWeek: 'Lun - Vie: 8:00 AM - 6:00 PM',
      scheduleSat: 'Sábados: 8:00 AM - 12:00 PM'
    };
    if (!saved) return defaults;
    try { return Object.assign({}, defaults, JSON.parse(saved)); } catch (e) { return defaults; }
  },

  saveCompanySettings: function(settings) {
    localStorage.setItem('wes_company_settings', JSON.stringify(settings));
  },

  // Gestión de Reseñas y Métricas de Calidad de Producto
  getProductReviews: function(productId) {
    const defaultReviews = [
      {
        id: 'rev-604-1',
        productId: 'odoo-21471',
        author: 'Ing. Carlos Mendoza',
        location: 'Moca, Espaillat',
        rating: 5.0,
        productQuality: 5.0,
        shippingQuality: 5.0,
        serviceQuality: 5.0,
        comment: 'Excelente motor CAME 800KG. Instalado en portón residencial de 6 metros. Movimiento suave y silencioso.',
        verified: true,
        date: '14 Sep 2026'
      },
      {
        id: 'rev-604-2',
        productId: 'odoo-21471',
        author: 'Lic. Ramona Peña',
        location: 'Santiago de los Caballeros',
        rating: 5.0,
        productQuality: 5.0,
        shippingQuality: 4.8,
        serviceQuality: 5.0,
        comment: 'Calidad italiana insuperable. El personal de WES me asesoró con la placa ZBX y la entrega fue el mismo día.',
        verified: true,
        date: '02 Sep 2026'
      },
      {
        id: 'rev-604-3',
        productId: 'odoo-21471',
        author: 'Manuel de Jesús Tavares',
        location: 'La Vega',
        rating: 4.8,
        productQuality: 5.0,
        shippingQuality: 5.0,
        serviceQuality: 4.8,
        comment: 'Robusto y potente. Chasis de aluminio inyectado de primera y los controles CAME tienen un alcance genial.',
        verified: true,
        date: '28 Ago 2026'
      }
    ];

    const saved = localStorage.getItem('wes_product_reviews');
    let allReviews = defaultReviews;
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          allReviews = [...defaultReviews, ...parsed.filter(p => !defaultReviews.some(d => d.id === p.id))];
        }
      } catch (e) {}
    }

    if (!productId) return allReviews;
    return allReviews.filter(r => r.productId === productId || r.productId === 'odoo-' + productId);
  },

  saveProductReview: function(review) {
    const saved = localStorage.getItem('wes_product_reviews');
    let reviews = [];
    if (saved) {
      try { reviews = JSON.parse(saved); } catch (e) { reviews = []; }
    }
    reviews.unshift(review);
    localStorage.setItem('wes_product_reviews', JSON.stringify(reviews));
  }
};

if (typeof window !== 'undefined') {
  window.INITIAL_PRODUCTS = INITIAL_PRODUCTS;
  window.StorageService = StorageService;
}
if (typeof module !== 'undefined') {
  module.exports = { INITIAL_PRODUCTS, StorageService };
}
